import pandas as pd
from pandas.tseries.offsets import CustomBusinessDay, CustomBusinessMonthBegin, CustomBusinessMonthEnd

# Example 1: CustomBusinessDay with microsecond offset on datetime64[s]
try:
    result1 = pd.date_range('2016-01-01', periods=3, freq='D', unit='s') + CustomBusinessDay(offset=pd.Timedelta(microseconds=500))
    probe("pd.date_range('2016-01-01', periods=3, freq='D', unit='s') + CustomBusinessDay(offset=pd.Timedelta(microseconds=500))", {
        "dtype": str(result1.dtype),
        "values": result1.tolist(),
        "repr": repr(result1)
    })
except Exception as e:
    probe("pd.date_range('2016-01-01', periods=3, freq='D', unit='s') + CustomBusinessDay(offset=pd.Timedelta(microseconds=500))", 
